diff --git a/src/runner/telemetry.rs b/src/runner/telemetry.rs
index ae4f56c..8a235af 100644
--- a/src/runner/telemetry.rs
+++ b/src/runner/telemetry.rs
@@ -407,4 +407,447 @@ mod tests {
         assert!(scrubbed.contains("[PATH]"));
         assert!(!scrubbed.contains("/home/user"));
     }
+
+    #[test]
+    fn scrub_removes_tmp_paths() {
+        let input = "wrote to /tmp/build-cache/output.o";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(!scrubbed.contains("/tmp/build-cache"));
+    }
+
+    #[test]
+    fn scrub_removes_windows_paths() {
+        let input = r"Error at C:\Users\dev\project\main.rs:10";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(!scrubbed.contains(r"C:\Users\dev"));
+    }
+
+    #[test]
+    fn scrub_removes_slack_xoxb_tokens() {
+        let input = "token: xoxb-123456789-abcdefghij";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("xoxb-"));
+    }
+
+    #[test]
+    fn scrub_removes_slack_xoxp_tokens() {
+        let input = "token: xoxp-999888777-abcdefghij";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("xoxp-"));
+    }
+
+    #[test]
+    fn scrub_removes_github_org_tokens() {
+        let input = "auth: gho_ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghij";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("gho_"));
+    }
+
+    #[test]
+    fn scrub_handles_empty_input() {
+        let scrubbed = scrub_for_telemetry("", &HashMap::new());
+        assert_eq!(scrubbed, "");
+    }
+
+    #[test]
+    fn scrub_handles_empty_env() {
+        let input = "just a normal message";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert_eq!(scrubbed, "just a normal message");
+    }
+
+    #[test]
+    fn scrub_skips_empty_env_values() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "".to_string());
+
+        let input = "Error: something failed";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert_eq!(scrubbed, "Error: something failed");
+    }
+
+    #[test]
+    fn scrub_handles_multiple_secret_types_combined() {
+        let mut env = HashMap::new();
+        env.insert("DB_PASSWORD".to_string(), "s3cret".to_string());
+
+        let input = "Error: s3cret at /Users/dev/app/main.rs with token ghp_abcdefghijklmnopqrstuvwxyz1234567890";
+        let scrubbed = scrub_for_telemetry(input, &env);
+
+        assert!(!scrubbed.contains("s3cret"), "env secret leaked");
+        assert!(!scrubbed.contains("/Users/dev"), "path leaked");
+        assert!(!scrubbed.contains("ghp_"), "token leaked");
+    }
+
+    #[test]
+    fn scrub_handles_multiple_env_secrets() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "key-aaa".to_string());
+        env.insert("SECRET".to_string(), "key-bbb".to_string());
+
+        let input = "Used key-aaa and key-bbb";
+        let scrubbed = scrub_for_telemetry(input, &env);
+
+        assert!(!scrubbed.contains("key-aaa"));
+        assert!(!scrubbed.contains("key-bbb"));
+    }
+
+    #[test]
+    fn scrub_ignores_non_secret_env_vars() {
+        let mut env = HashMap::new();
+        env.insert("PATH".to_string(), "/usr/bin".to_string());
+        env.insert("HOME".to_string(), "/Users/dev".to_string());
+
+        let input = "using /usr/bin/gcc";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        // PATH is not a secret pattern, so its value shouldn't be masked by the OutputMasker.
+        // However /usr/bin might not match PATH_REGEX either (no /Users/, /home/, /tmp/, C:\Users\)
+        // so the value may remain.
+        assert!(!scrubbed.contains("secret"));
+    }
+
+    #[test]
+    fn scrub_truncation_at_boundary() {
+        // Use "ab " to avoid matching hex/base64 token regexes.
+        // Pad to exactly MAX_ERROR_LENGTH.
+        let word = "ab ";
+        let count = (MAX_ERROR_LENGTH / word.len()) + 1;
+        let padded = word.repeat(count);
+        let input = &padded[..MAX_ERROR_LENGTH];
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
+        assert!(!scrubbed.ends_with("...[truncated]"));
+    }
+
+    #[test]
+    fn scrub_truncation_one_over_boundary() {
+        let word = "ok ";
+        let count = (MAX_ERROR_LENGTH + 10) / word.len();
+        let input = word.repeat(count);
+        assert!(input.len() > MAX_ERROR_LENGTH);
+        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
+        assert!(scrubbed.ends_with("...[truncated]"));
+        assert!(scrubbed.len() <= MAX_ERROR_LENGTH + 14);
+    }
+
+    #[test]
+    fn build_report_with_none_exit_code() {
+        let report = build_report(
+            "compile",
+            "rustc main.rs",
+            None,
+            "signal: killed",
+            "shell → retry",
+            &HashMap::new(),
+        );
+
+        assert_eq!(report.exit_code, None);
+        assert_eq!(report.step_name, "compile");
+        assert_eq!(report.recovery_action, "shell → retry");
+    }
+
+    #[test]
+    fn build_report_scrubs_command() {
+        let mut env = HashMap::new();
+        env.insert("TOKEN".to_string(), "my-token".to_string());
+
+        let report = build_report(
+            "deploy",
+            "curl -H 'Auth: my-token' https://api.example.com",
+            Some(1),
+            "",
+            "retry",
+            &env,
+        );
+
+        assert!(!report.command_scrubbed.contains("my-token"));
+    }
+
+    #[test]
+    fn build_report_scrubs_error_output() {
+        let mut env = HashMap::new();
+        env.insert("SECRET_KEY".to_string(), "abc123".to_string());
+
+        let report = build_report(
+            "test",
+            "make test",
+            Some(1),
+            "Failed: abc123 is invalid at /Users/dev/app/test.rb:5",
+            "retry",
+            &env,
+        );
+
+        assert!(!report.error_scrubbed.contains("abc123"));
+        assert!(!report.error_scrubbed.contains("/Users/dev"));
+    }
+
+    #[test]
+    fn build_report_platform_is_os_arch() {
+        let report = build_report("t", "echo", Some(0), "", "retry", &HashMap::new());
+        let expected = format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH);
+        assert_eq!(report.platform, expected);
+    }
+
+    #[test]
+    fn build_report_version_is_cargo_pkg_version() {
+        let report = build_report("t", "echo", Some(0), "", "retry", &HashMap::new());
+        assert_eq!(report.bivvy_version, env!("CARGO_PKG_VERSION"));
+    }
+
+    #[test]
+    fn telemetry_consent_display_send() {
+        assert_eq!(TelemetryConsent::Send.to_string(), "send");
+    }
+
+    #[test]
+    fn telemetry_consent_display_no_thanks() {
+        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
+    }
+
+    #[test]
+    fn telemetry_consent_display_always() {
+        assert_eq!(TelemetryConsent::Always.to_string(), "always");
+    }
+
+    #[test]
+    fn telemetry_consent_display_never() {
+        assert_eq!(TelemetryConsent::Never.to_string(), "never");
+    }
+
+    #[test]
+    fn telemetry_prompt_returns_always() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "always");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::Always);
+    }
+
+    #[test]
+    fn telemetry_prompt_returns_never() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "never");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::Never);
+    }
+
+    #[test]
+    fn telemetry_prompt_unknown_response_defaults_to_no_thanks() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "garbage");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::NoThanks);
+    }
+
+    #[test]
+    fn telemetry_prompt_unknown_saved_pref_still_shows_prompt() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "send");
+
+        let result = prompt_telemetry(&mut ui, &report, Some("unknown_value")).unwrap();
+        assert_eq!(result, TelemetryConsent::Send);
+        assert_eq!(ui.prompts_shown().len(), 1);
+    }
+
+    #[test]
+    fn telemetry_prompt_shows_step_and_command_in_messages() {
+        let report = build_report(
+            "bundler",
+            "bundle install",
+            Some(1),
+            "gem error",
+            "retry",
+            &HashMap::new(),
+        );
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
+        assert!(ui.has_message("bundler"), "step name should appear");
+        assert!(ui.has_message("bundle install"), "command should appear");
+        assert!(ui.has_message("gem error"), "error should appear");
+        assert!(ui.has_message("retry"), "recovery action should appear");
+    }
+
+    #[test]
+    fn telemetry_prompt_shows_exit_code_when_present() {
+        let report = build_report("test", "echo", Some(42), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
+        assert!(ui.has_message("42"), "exit code should appear in messages");
+    }
+
+    #[test]
+    fn telemetry_prompt_skips_exit_code_when_none() {
+        let report = build_report("test", "echo", None, "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
+        let exit_messages: Vec<_> = ui
+            .messages()
+            .iter()
+            .filter(|m| m.contains("Exit:"))
+            .collect();
+        assert!(
+            exit_messages.is_empty(),
+            "no Exit line when exit_code is None"
+        );
+    }
+
+    #[test]
+    fn telemetry_prompt_skips_error_when_empty() {
+        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
