+    #[test]
+    fn scrub_removes_tmp_paths() {
+        let input = "wrote to /tmp/build-cache/output.o";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(!scrubbed.contains("/tmp/build-cache"));
+    }
+
+    #[test]
+    fn scrub_removes_windows_paths() {
+        let input = r"Error at C:\Users\dev\project\main.rs:10";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(!scrubbed.contains(r"C:\Users\dev"));
+    }
+
+    #[test]
+    fn scrub_removes_slack_xoxb_tokens() {
+        let input = "token: xoxb-123456789-abcdefghij";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("xoxb-"));
+    }
+
+    #[test]
+    fn scrub_removes_slack_xoxp_tokens() {
+        let input = "token: xoxp-999888777-abcdefghij";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("xoxp-"));
+    }
+
+    #[test]
+    fn scrub_removes_github_org_tokens() {
+        let input = "auth: gho_ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghij";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("gho_"));
+    }
+
+    #[test]
+    fn scrub_handles_empty_input() {
+        let scrubbed = scrub_for_telemetry("", &HashMap::new());
+        assert_eq!(scrubbed, "");
+    }
+
+    #[test]
+    fn scrub_handles_empty_env() {
+        let input = "just a normal message";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert_eq!(scrubbed, "just a normal message");
+    }
+
+    #[test]
+    fn scrub_skips_empty_env_values() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "".to_string());
+
+        let input = "Error: something failed";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert_eq!(scrubbed, "Error: something failed");
+    }
+
+    #[test]
+    fn scrub_handles_multiple_secret_types_combined() {
+        let mut env = HashMap::new();
+        env.insert("DB_PASSWORD".to_string(), "s3cret".to_string());
+
+        let input = "Error: s3cret at /Users/dev/app/main.rs with token ghp_abcdefghijklmnopqrstuvwxyz1234567890";
+        let scrubbed = scrub_for_telemetry(input, &env);
+
+        assert!(!scrubbed.contains("s3cret"), "env secret leaked");
+        assert!(!scrubbed.contains("/Users/dev"), "path leaked");
+        assert!(!scrubbed.contains("ghp_"), "token leaked");
+    }
+
+    #[test]
+    fn scrub_handles_multiple_env_secrets() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "key-aaa".to_string());
+        env.insert("SECRET".to_string(), "key-bbb".to_string());
+
+        let input = "Used key-aaa and key-bbb";
+        let scrubbed = scrub_for_telemetry(input, &env);
+
+        assert!(!scrubbed.contains("key-aaa"));
+        assert!(!scrubbed.contains("key-bbb"));
+    }
+
+    #[test]
+    fn scrub_ignores_non_secret_env_vars() {
+        let mut env = HashMap::new();
+        env.insert("PATH".to_string(), "/usr/bin".to_string());
+        env.insert("HOME".to_string(), "/Users/dev".to_string());
+
+        let input = "using /usr/bin/gcc";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        // PATH is not a secret pattern, so its value shouldn't be masked by the OutputMasker.
+        // However /usr/bin might not match PATH_REGEX either (no /Users/, /home/, /tmp/, C:\Users\)
+        // so the value may remain.
+        assert!(!scrubbed.contains("secret"));
+    }
+
+    #[test]
+    fn scrub_truncation_at_boundary() {
+        // Use "ab " to avoid matching hex/base64 token regexes.
+        // Pad to exactly MAX_ERROR_LENGTH.
+        let word = "ab ";
+        let count = (MAX_ERROR_LENGTH / word.len()) + 1;
+        let padded = word.repeat(count);
+        let input = &padded[..MAX_ERROR_LENGTH];
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
+        assert!(!scrubbed.ends_with("...[truncated]"));
+    }
+
+    #[test]
+    fn scrub_truncation_one_over_boundary() {
+        let word = "ok ";
+        let count = (MAX_ERROR_LENGTH + 10) / word.len();
+        let input = word.repeat(count);
+        assert!(input.len() > MAX_ERROR_LENGTH);
+        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
+        assert!(scrubbed.ends_with("...[truncated]"));
+        assert!(scrubbed.len() <= MAX_ERROR_LENGTH + 14);
+    }
+
+    #[test]
